"""Manual source extraction, 2026-10-06. Values are source reported, never risk scores.

One record = one study / compound-drug relationship / experimental evidence context.
Combination interventions have one anchor compound and an explicit co-compound field;
they are not duplicated for every ingredient. Negative findings are evidence controls.
"""
E=[]
def add(compound,drug,source,evidence,design,pop,effect,mechanism='',category='',direction='',**kw):
    r=dict(compound=compound,drug=drug,source=source,evidence_type=evidence,study_type=design,species_or_population=pop,effect_description=effect,mechanism=mechanism,mechanism_category=category,effect_direction=direction)
    r.update(kw); E.append(r)
